/**
 * Writes scripts/data/car-t-saudi-arabia-market-research.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-car-t-saudi-arabia-market-research-cover.mjs.
 *
 *   node scripts/generate-car-t-saudi-arabia-market-research-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/car-t-saudi-arabia-market-research.json');

export const ANNA_CUBAN_SANITY_ID = '7acabff7-aae6-4d8a-a667-91e21a235bcb';

/** Every blogPost field that applies to a healthcare-silo article. */
export const CART_KSA_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-car-t-saudi-arabia-market-research.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.CART_KSA_EXECUTIVE_SUMMARY_HTML).replace(/^Short answer:\s*/i, '');
  const firstParagraph = stripHtml(mod.CART_KSA_BODY_HTML.split('<h2')[0])
    .replace(/^CAR-T Saudi Arabia market research[\s\S]*?This briefing uses only published sources\./, '')
    .trim();

  return {
    seo: {
      metaTitle: mod.CART_KSA_META_TITLE,
      metaDescription: mod.CART_KSA_META_DESCRIPTION,
      focusKeyword: 'CAR-T Saudi Arabia market research',
      keywords: [
        'CAR-T Saudi Arabia market research',
        'ADC Saudi Arabia',
        'bispecific antibodies Saudi Arabia',
        'KFSHRC CAR-T',
        'KAMC formulary',
        'tertiary centre adoption',
        'NPT0047/25',
        'Saudi oncology market research',
      ],
      canonicalUrl: mod.CART_KSA_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.CART_KSA_META_TITLE,
      ogDescription: mod.CART_KSA_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.CART_KSA_COVER_IMAGE}`,
        alt: mod.CART_KSA_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.CART_KSA_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.CART_KSA_SLUG },
    excerpt: mod.CART_KSA_EXCERPT,
    publishedAt: mod.CART_KSA_PUBLISHED_ISO,
    updatedAt: mod.CART_KSA_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: ANNA_CUBAN_SANITY_ID,
      name: 'Anna Cuban',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.CART_KSA_HERO_IMAGE}`,
      alt: mod.CART_KSA_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for CAR-T Saudi Arabia market research at tertiary centres',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.CART_KSA_TAGS],
    country: 'Saudi Arabia',
    language: 'en',
    readingTime: mod.CART_KSA_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.CART_KSA_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.CART_KSA_EXECUTIVE_SUMMARY_HTML}\n\n${mod.CART_KSA_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'What CAR-T Saudi Arabia market research should measure',
        type: 'table',
        data: JSON.stringify(
          mod.CART_KSA_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'KFSH&RC CAR-T series; SSBMT 2024; NUPCO NPT0047/25; Saudi Cancer Registry 2024; PPRI 2024',
      },
      portableText(
        firstParagraph ||
          'CAR-T Saudi Arabia market research is a tertiary-centre adoption problem before it is a national-tender problem.',
      ),
    ],
    faq: mod.CART_KSA_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: [
      'nupco-tender-market-research-saudi-arabia',
      'hematology-market-research-saudi-arabia',
      'how-to-choose-healthcare-market-research-agency-saudi-arabia',
    ],
    ctaSection: { ...mod.CART_KSA_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.CART_KSA_BODY_HTML),
    factCheckedAt: mod.CART_KSA_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/car-t-saudi-arabia-market-research-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of CART_KSA_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(
    `Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`,
  );
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
